import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Garis Besar Protokol Arkeologi","description":"","frontmatter":{},"headers":[],"relativePath":"id/84-考古协议总纲.md","filePath":"id/84-考古协议总纲.md","lastUpdated":1789183869000}'),r={name:"id/84-考古协议总纲.md"};function u(l,a,k,o,s,d){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="garis-besar-protokol-arkeologi" tabindex="-1">Garis Besar Protokol Arkeologi <a class="header-anchor" href="#garis-besar-protokol-arkeologi" aria-label="Permalink to &quot;Garis Besar Protokol Arkeologi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>84</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Protokol arkeologi, cermin salinan, ruang terisolasi, hanya mengembalikan pengetahuan, polusi rendah</td></tr></tbody></table><h2 id="_1-posisi-dan-tujuan-protokol-arkeologi" tabindex="-1">1. Posisi dan Tujuan Protokol Arkeologi <a class="header-anchor" href="#_1-posisi-dan-tujuan-protokol-arkeologi" aria-label="Permalink to &quot;1. Posisi dan Tujuan Protokol Arkeologi&quot;">​</a></h2><p>Arkeologi antar bidang dan arkeologi mundurnya waktu adalah sarana penting bagi peradaban simbiosis neo untuk memperoleh pengetahuan sejarah dan memahami evolusi alam semesta. Namun, tindakan arkeologi itu sendiri memiliki risiko yang tinggi — masuk langsung ke bidang target atau periode target untuk melakukan penggalian arkeologi dapat menyebabkan kerusakan fisik, gangguan hukum, dan polusi budaya pada objek target. Untuk mengatur tindakan arkeologi dan mengurangi risiko arkeologi, Hengyuanzhou telah merumuskan &quot;Garis Besar Protokol Arkeologi&quot; yang terpadu, sebagai norma operasional dasar untuk semua kegiatan arkeologi antar bidang dan mundurnya waktu.</p><p>Tujuan inti protokol arkeologi dapat diringkas dalam &quot;tiga maksimalisasi&quot;: memaksimalkan perolehan pengetahuan sejarah yang lengkap, meminimalkan gangguan dan kerusakan pada objek target, memaksimalkan keamanan personel arkeologi. Ada ketegangan intrinsik antara ketiga tujuan ini — kelengkapan perolehan pengetahuan seringkali memerlukan kontak yang lebih mendalam, sementara prinsip gangguan rendah membatasi kedalaman kontak. Seluruh desain institusional protokol arkeologi bertujuan untuk menemukan keseimbangan optimal di antara ketiganya.</p><p>Protokol arkeologi berlaku untuk skenario berikut: penyelidikan arkeologi terhadap reruntuhan peradaban di bidang yang tidak diketahui, restorasi sejarah peradaban yang telah punah melalui mundurnya waktu, arkeologi mendalam pada tingkat hukum terhadap reruntuhan kuno di bidang sendiri, dan penggalian penyelamatan terhadap peninggalan purba di bidang dengan hukum rusak.</p><h2 id="_2-tiga-elemen-skema-arkeologi" tabindex="-1">2. Tiga Elemen Skema Arkeologi <a class="header-anchor" href="#_2-tiga-elemen-skema-arkeologi" aria-label="Permalink to &quot;2. Tiga Elemen Skema Arkeologi&quot;">​</a></h2><p>Skema arkeologi standar Hengyuanzhou terdiri dari tiga elemen inti, yang disebut &quot;tiga elemen arkeologi&quot;:</p><h3 id="_2-1-cermin-salinan" tabindex="-1">2.1 Cermin Salinan <a class="header-anchor" href="#_2-1-cermin-salinan" aria-label="Permalink to &quot;2.1 Cermin Salinan&quot;">​</a></h3><p>Cermin salinan adalah perangkat penyalinan presisi tinggi berdasarkan hukum hukum ruang, mampu melakukan penyalinan lengkap 1:1 terhadap struktur materi, energi, dan informasi di area target tanpa menyentuh objek asli. Prinsip kerja cermin salinan adalah memindai semua status partikel dan distribusi medan energi di area target melalui hukum ruang, kemudian membangun kembali salinan yang identik di ruang terisolasi. Proses penyalinan tidak mengubah status apa pun dari objek asli,因此 tidak menyebabkan gangguan fisik apa pun pada lokasi arkeologi.</p><p>Presisi penyalinan cermin salinan mencapai tingkat subatomik, mampu mengembalikan sepenuhnya struktur materi, sisa energi, jejak kesadaran, bahkan fragmen rantai kausal di area target. Ruang lingkup penyalinan dapat disesuaikan sesuai kebutuhan arkeologi, unit penyalinan terkecil adalah satu artefak, yang terbesar dapat mencakup seluruh kelompok reruntuhan. Waktu penyalinan tergantung pada ukuran ruang lingkup penyalinan, penyalinan satu artefak biasanya selesai dalam beberapa menit, penyalinan kelompok reruntuhan besar mungkin memerlukan beberapa hari.</p><h3 id="_2-2-ruang-terisolasi" tabindex="-1">2.2 Ruang Terisolasi <a class="header-anchor" href="#_2-2-ruang-terisolasi" aria-label="Permalink to &quot;2.2 Ruang Terisolasi&quot;">​</a></h3><p>Ruang terisolasi adalah wilayah hukum independen yang dibangun melalui teknologi pengaturan hukum ruang, digunakan untuk menampung salinan arkeologi yang dihasilkan oleh cermin salinan, dan sebagai tempat kerja personel arkeologi. Ruang terisolasi dan bidang target atau periode target dipisahkan oleh hambatan hukum yang lengkap, memastikan bahwa operasi arkeologi tidak menyebabkan dampak terbalik apa pun pada target asli.</p><p>Parameter hukum di dalam ruang terisolasi dapat disesuaikan sesuai kebutuhan arkeologi, termasuk: mensimulasikan parameter lingkungan bidang target untuk memastikan stabilitas salinan artefak, mengatur medan hukum analisis khusus untuk membantu penelitian arkeologi, dan membangun medan pencegahan polusi yang ketat untuk mencegah kebocoran energi dan kesadaran personel arkeologi. Ukuran ruang terisolasi dapat diperluas sesuai kebutuhan, yang terbesar dapat menampung salinan reruntuhan tingkat kota seluruhnya.</p><h3 id="_2-3-hanya-mengembalikan-pengetahuan" tabindex="-1">2.3 Hanya Mengembalikan Pengetahuan <a class="header-anchor" href="#_2-3-hanya-mengembalikan-pengetahuan" aria-label="Permalink to &quot;2.3 Hanya Mengembalikan Pengetahuan&quot;">​</a></h3><p>&quot;Hanya mengembalikan pengetahuan&quot; adalah salah satu prinsip inti protokol arkeologi, yang berarti bahwa apa yang diperoleh dari objek target selama proses arkeologi hanya boleh berupa pengetahuan dan informasi abstrak, tidak boleh mengembalikan materi, energi, atau makhluk hidup apa pun. Setelah personel arkeologi meneliti salinan di ruang terisolasi, hanya boleh membawa kesimpulan penelitian, catatan data, dan laporan analisis kembali ke bidang自己 dalam bentuk informasi murni; salinan itu sendiri dan sampel materi apa pun yang diekstraksi dari salinan harus dihancurkan di dalam ruang terisolasi.</p><p>Tujuan mendasar dari prinsip ini adalah untuk mencegah polusi antar bidang dan gangguan garis waktu. Bahkan sebutir debu yang diekstraksi dari salinan dapat membawa informasi hukum bidang target,一旦 masuk ke jaringan hukum bidang自己, dapat memicu reaksi berantai yang tidak terduga. Oleh karena itu, &quot;hanya mengembalikan pengetahuan&quot; bukanlah saran operasional yang dapat dinegosiasikan, melainkan prinsip kaku dengan kekuatan hukum yang memaksa.</p><h2 id="_3-proses-standar-operasi-arkeologi" tabindex="-1">3. Proses Standar Operasi Arkeologi <a class="header-anchor" href="#_3-proses-standar-operasi-arkeologi" aria-label="Permalink to &quot;3. Proses Standar Operasi Arkeologi&quot;">​</a></h2><p>Operasi arkeologi antar bidang atau mundurnya waktu yang lengkap mengikuti proses standar berikut:</p><table tabindex="0"><thead><tr><th>Tahap</th><th>Konten Operasi</th><th>Pihak yang Bertanggung Jawab</th><th>Referensi Durasi</th></tr></thead><tbody><tr><td>Tahap Pertama: Persetujuan Proyek</td><td>Mengajukan permohonan arkeologi, menjelaskan tujuan, ruang lingkup, dan skema arkeologi, mendapatkan izin penyeberangan Tingkat A atau izin mundur</td><td>Tim arkeologi → Biro Administrasi Bidang / Komite Hukum Waktu</td><td>7-30 hari</td></tr><tr><td>Tahap Kedua: Pengamatan Terlebih Dahulu</td><td>Sesuai pedoman &quot;pengamatan terlebih dahulu, kemudian intervensi terbatas&quot;, melakukan pengamatan murni selama tidak kurang dari 72 jam di area target</td><td>Tim arkeologi</td><td>Lebih dari 72 jam</td></tr><tr><td>Tahap Ketiga: Penerapan Cermin Salinan</td><td>Menerapkan cermin salinan di lokasi aman dekat area target, mengatur ruang lingkup penyalinan dan parameter presisi</td><td>Tim teknis</td><td>Beberapa jam hingga beberapa hari</td></tr><tr><td>Tahap Keempat: Generasi Salinan</td><td>Mengaktifkan cermin salinan, menyalin area target sepenuhnya ke ruang terisolasi yang telah dibangun sebelumnya</td><td>Tim teknis</td><td>Beberapa menit hingga beberapa hari</td></tr><tr><td>Tahap Kelima: Arkeologi di Ruang Terisolasi</td><td>Personel arkeologi masuk ke ruang terisolasi, melakukan penggalian, analisis, dan penelitian sistematis terhadap salinan</td><td>Tim arkeologi</td><td>Beberapa hari hingga beberapa tahun</td></tr><tr><td>Tahap Keenam: Penyusunan Pengetahuan</td><td>Menyusun hasil arkeologi, membentuk laporan penelitian dan basis data pengetahuan, memastikan semua hasil dalam bentuk informasi murni</td><td>Tim arkeologi</td><td>Beberapa hari hingga beberapa bulan</td></tr><tr><td>Tahap Ketujuh: Evakuasi dan Penghancuran</td><td>Personel arkeologi dievakuasi dari ruang terisolasi, menghancurkan semua salinan materi dan sisa energi, menutup ruang terisolasi</td><td>Tim teknis + Tim pengawas</td><td>Beberapa jam</td></tr><tr><td>Tahap Kedelapan: Audit Pasca</td><td>Menyerahkan laporan arkeologi lengkap, menerima audit pasca dari Komite Audit Hukum Waktu atau Biro Administrasi Bidang</td><td>Komite audit</td><td>Dalam 30 hari</td></tr></tbody></table><h2 id="_4-kualifikasi-dan-persyaratan-etika-personel-arkeologi" tabindex="-1">4. Kualifikasi dan Persyaratan Etika Personel Arkeologi <a class="header-anchor" href="#_4-kualifikasi-dan-persyaratan-etika-personel-arkeologi" aria-label="Permalink to &quot;4. Kualifikasi dan Persyaratan Etika Personel Arkeologi&quot;">​</a></h2><p>Personel yang terlibat dalam arkeologi antar bidang dan mundurnya waktu harus memiliki kualifikasi berikut: kultivasi tahap ketiga atau lebih tinggi dari sistem pengaturan hukum ruang, sertifikasi kualifikasi dari komite etika arkeologi, menyelesaikan tidak kurang dari 100 jam pelatihan arkeologi simulasi, dan tidak memiliki catatan pelanggaran hukum simbiosis.</p><p>Personel arkeologi harus mematuhi persyaratan etika berikut: menghormati budaya dan keyakinan peradaban target, tidak melakukan diskriminasi budaya atau penilaian nilai dalam penelitian; melindungi integritas lokasi arkeologi, tidak merusak struktur reruntuhan untuk mendapatkan artefak; mencatat dan melaporkan temuan arkeologi dengan jujur, tidak memalsukan atau menyembunyikan data arkeologi; dan mematuhi prinsip &quot;hanya mengembalikan pengetahuan&quot;, tidak membawa sampel materi apa pun secara pribadi keluar dari ruang terisolasi.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Garis Besar Protokol Arkeologi adalah jembatan institusional yang dibangun Hengyuanzhou antara eksplorasi pengetahuan dan perlindungan peradaban. Dengan tiga elemen — cermin salinan, ruang terisolasi, dan hanya mengembalikan pengetahuan — sebagai dukungan teknis, proses standar sebagai kerangka operasional, dan kualifikasi personel serta persyaratan etika sebagai jaminan kemanusiaan, ia membangun paradigma arkeologi &quot;polusi rendah, efisiensi tinggi, dapat dilacak&quot;. Paradigma ini memastikan bahwa Hengyuanzhou, dalam mengejar kebenaran sejarah, selalu menjaga rasa hormat tertinggi terhadap peradaban dan zaman lain.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>85-Skema Arkeologi Jarak Jauh dengan Cermin Salinan</li><li>86-Proses Polusi Rendah di Ruang Terisolasi</li><li>87-Prinsip Hanya Mengembalikan Pengetahuan</li></ul>',27)])])}const p=e(r,[["render",u]]);export{m as __pageData,p as default};
